package com.hbm.client.designator;
import com.hbm.item.designator.DesignatorContent;import com.hbm.item.designator.advanced.AdvancedDesignatorContent;import net.minecraft.client.gui.*;import net.minecraft.client.gui.screens.inventory.tooltip.TooltipRenderUtil;import net.minecraft.world.item.ItemStack;
/** Original GuiInfoContainer.drawStackText2rows,18pixel icons and1000ms current-example red border. */
public final class DesignatorHints{public static void render(GuiGraphics g,Font font,int width,int height,int x,int y){ItemStack[] stacks={new ItemStack(DesignatorContent.DESIGNATOR.get()),new ItemStack(AdvancedDesignatorContent.RANGE.get()),new ItemStack(AdvancedDesignatorContent.MANUAL.get())};int selected=(int)(System.currentTimeMillis()%3000/1000);var name=stacks[selected].getHoverName();int w=Math.max(54,font.width(name)),h=28,mx=x+12,my=y-12;if(mx+w>width)mx-=28+w;if(my+h+6>height)my=height-h-6;g.flush();TooltipRenderUtil.renderTooltipBackground(g,mx,my,w,h,400);g.pose().pushPose();g.pose().translate(0,0,400);for(int i=0;i<3;i++){if(i==selected){g.fill(mx+18*i-1,my-1,mx+18*i+17,my+17,0xffff0000);g.fill(mx+18*i,my,mx+18*i+16,my+16,0xffb0b0b0);}g.renderItem(stacks[i],mx+18*i,my);g.renderItemDecorations(font,stacks[i],mx+18*i,my,i==selected?"0":null);}g.drawString(font,name,mx,my+20,-1,true);g.pose().popPose();}private DesignatorHints(){}}
